// 新增函数：创建最小纹理（1x1透明纹理）
static LPTEXTURE create_minimal_texture(void) {
    LPTEXTURE tex = R_AllocateTexture(1, 1);
    COLOR32 pixel = { .r = 255, .g = 255, .b = 255, .a = 0 };
    R_LoadTextureMipLevel(tex, 0, &pixel, 1, 1);
    return tex;
}

// 新增函数：创建或更新动态图集纹理
static LPTEXTURE update_dynamic_texture(font_t *font) {
    if (!font->dynamic_atlas || font->atlas_width <= 0 || font->atlas_height <= 0) {
        // 还没有任何字符，创建最小纹理
        return create_minimal_texture();
    }
